-- Dynamic application fixes: atomic conversations and realtime team updates.
create or replace function public.get_or_create_property_conversation(target_property uuid,target_seller uuid) returns uuid language plpgsql security definer set search_path=public as $$declare buyer uuid:=auth.uid();conversation_id uuid;actual_seller uuid;begin if buyer is null then raise exception 'authentication required';end if;select owner_id into actual_seller from properties where id=target_property and status='published';if actual_seller is null then raise exception 'property is unavailable';end if;if target_seller<>actual_seller then raise exception 'invalid seller';end if;if buyer=actual_seller then raise exception 'cannot message your own listing';end if;select c.id into conversation_id from conversations c join conversation_members buyer_member on buyer_member.conversation_id=c.id and buyer_member.user_id=buyer join conversation_members seller_member on seller_member.conversation_id=c.id and seller_member.user_id=actual_seller where c.property_id=target_property::text limit 1;if conversation_id is null then insert into conversations(property_id) values(target_property::text) returning id into conversation_id;insert into conversation_members(conversation_id,user_id) values(conversation_id,buyer),(conversation_id,actual_seller);end if;return conversation_id;end;$$;
revoke all on function public.get_or_create_property_conversation(uuid,uuid) from public;grant execute on function public.get_or_create_property_conversation(uuid,uuid) to authenticated;
do $$begin alter publication supabase_realtime add table public.team_members;exception when duplicate_object then null;end$$;
-- Ensure property records remain directly addressable by their UUID while RLS
-- continues to hide drafts from non-owners.
create index if not exists properties_id_status_idx on public.properties(id,status);
